import { dirname, join, normalize } from 'node:path';
import { humanTurns, assistantTextAfter, classificationLine, classesIn } from './session-transcript.mjs';
import { addedLines } from './line-scanning.mjs';
import { extractLinks } from './markdown.mjs';

// The fluent check-the-work surface over ctx. Every accessor is null-safe — no
// transcript, no merge-base, an empty branch all yield empty results — so a rule
// reads as one chain with no guard ladders. Mechanism only: a rule still owns
// its patterns, file filters, and failure text.
//
// A rule declaring `scope: 'work'` receives this object as its `run` argument
// (runRule dispatches); check-the-world rules keep the raw ctx until a fluent
// world object exists. The raw surface a work rule still needs (files, read,
// exists, …) is delegated here, so a work rule — and the structural helpers it
// calls, e.g. findExtensionManifest — never touches ctx itself.
export const work = (ctx) => new Work(ctx);

// The single dispatch seam: the runner and every rule test invoke rules through
// this, so a rule's scope decides its context in exactly one place. Extra args
// pass through (some rules take test-only options after the context).
export const runRule = (rule, ctx, ...args) => rule.run(rule.scope === 'work' ? work(ctx) : ctx, ...args);

// Null-object for "no such turn": every accessor answers emptily, so a chain
// ending in .last() never needs an existence guard before its predicates.
const NO_TURN = {
  exists: false, text: '', timestamp: null,
  excerpt: () => '', reply: () => '', classified: () => false,
  classes: () => new Set(), time: () => 0,
};

class Turn {
  constructor(entries, { index, timestamp, text }) {
    this.entries = entries;
    this.index = index;
    this.timestamp = timestamp;
    this.text = text;
    this.exists = true;
  }

  excerpt(n) { return this.text.replace(/\s+/g, ' ').slice(0, n); }
  reply() { return assistantTextAfter(this.entries, this.index); }
  classified() { return classificationLine(this.reply()) !== null; }
  classes() { return classesIn(classificationLine(this.reply())); }
  time() { return Date.parse(this.timestamp ?? '') || 0; }
}

// Array subclass so filter/map stay chainable and .last() survives them.
class Turns extends Array {
  last() { return this.length ? this[this.length - 1] : NO_TURN; }
}

class Conversation {
  constructor(entries) { this.entries = entries ?? []; }

  ownerTurns() {
    const turns = new Turns();
    for (const t of humanTurns(this.entries)) turns.push(new Turn(this.entries, t));
    return turns;
  }
}

class Work {
  constructor(ctx) { this.ctx = ctx; }

  get branch() { return this.ctx.branch; }
  get baseRef() { return this.ctx.baseRef; }
  get commits() { return this.ctx.commits; }
  get files() { return this.ctx.files; }
  get changedFiles() { return this.ctx.changedFiles; }
  get deleted() { return this.ctx.deleted; }
  get tracked() { return this.ctx.tracked; }
  // The discovered pack objects (runner-attached) and the normalized config —
  // the pair a rule that reasons over pack metadata (e.g. adoption-interview
  // state) hands to the interview helpers, without reaching into ctx itself.
  get packs() { return this.ctx.packs ?? []; }
  get config() { return this.ctx.config; }
  read(path) { return this.ctx.read(path); }
  readBase(path) { return this.ctx.readBase(path); }
  exists(path) { return this.ctx.exists(path); }
  packConfig(id) { return this.ctx.config?.packConfig?.[id]; }

#!/usr/bin/env node
// Claude Code PreToolUse guard, two duties:
//  - a Bash command that deletes a remote branch is blocked (the delete-push fails
//    in this environment, so it can never succeed);
//  - a file tool (Edit, Write, NotebookEdit) aimed at a path one of an active
//    pack's skills names under `force-load-on-file-edits-paths` is blocked until the
//    session has loaded that skill — so the skill is read before the first edit
//    exists, not after a Stop-time finding has sent the agent back over work done.
// Exit 2 blocks the tool call and feeds stderr back to the agent; the block is the
// one message the agent needs. Registered per-repo — see bootstrap.md.
import { existsSync, readFileSync } from 'node:fs';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { hooklog } from '../checks/helpers/hook-log.mjs';
import { parseEntries, skillLoads } from '../checks/helpers/session-transcript.mjs';
import { pathScopedSkills, missingSkillsFor } from '../pack_loader/path-scoped-skills.mjs';
import { settingsPath } from '../settings-file.mjs';

// The file a tool is about to write, repo-relative with forward slashes — or null
// when the tool names no file or the file is outside the project (nothing here
// scopes a path the repo does not own).
function targetPath(payload, projectRoot) {
  const input = payload.tool_input ?? {};
  const raw = payload.tool_name === 'NotebookEdit' ? input.notebook_path : input.file_path;
  if (typeof raw !== 'string' || !raw) return null;
  const abs = isAbsolute(raw) ? raw : resolve(projectRoot, raw);
  const rel = relative(projectRoot, abs);
  if (!rel || rel.startsWith('..') || isAbsolute(rel)) return null;
  return rel.split(sep).join('/');
}

async function activePacks(projectRoot) {
  // This module lives at <corpus>/engine/hooks/ — the same root the mount hook
  // resolves the registry from, so the canon runs it from its own tree.
  const corpusRoot = dirname(dirname(dirname(fileURLToPath(import.meta.url))));
  let declared = [];
  const configPath = settingsPath(projectRoot);
  if (existsSync(configPath)) {
    const raw = JSON.parse(readFileSync(configPath, 'utf8'));
    if (Array.isArray(raw.packs)) declared = raw.packs;
  }
  const { loadPacks, isActive } = await import(join(corpusRoot, 'engine', 'pack_loader', 'pack-registry.mjs'));
  const packs = await loadPacks({ localRoot: projectRoot });
  return packs.filter((p) => isActive(p, { packs: declared }));
}

function loadedSkills(transcriptPath) {
  if (!transcriptPath || !existsSync(transcriptPath)) return [];
  try { return skillLoads(parseEntries(readFileSync(transcriptPath, 'utf8'))); } catch { return []; }
}

const FILE_TOOLS = new Set(['Edit', 'Write', 'NotebookEdit']);

async function guardFileTool(payload) {
  const projectRoot = process.env.CLAUDE_PROJECT_DIR || process.cwd();
  const path = targetPath(payload, projectRoot);
  if (!path) return;
  const declarations = pathScopedSkills(await activePacks(projectRoot));
  if (!declarations.length) return;
  const missing = missingSkillsFor(path, declarations, loadedSkills(payload.transcript_path));
  if (!missing.length) return;
  const names = missing.map((d) => d.skill);
  hooklog('PreToolUse', `done exit=2 skill-not-loaded ${path} needs ${names.join(',')}`);
  // Reading the skill's own file is a load too (the transcript reader counts it), so
  // the message carries that path beside the Skill call.
  const skillFile = (d) => relative(projectRoot, join(d.dir, 'SKILL.md')).split(sep).join('/');
  process.stderr.write(
    `Blocked: ${path} is edited only with the ${names.map((n) => `\`${n}\``).join(' and ')} skill loaded `
    + `(the ${[...new Set(missing.map((d) => d.pack))].join(', ')} pack's skill forces itself for ${missing.map((d) => d.files).join(', ')}). `
    + `Load it first — Skill tool, ${names.map((n) => `skill: "${n}"`).join(', ')}, or Read ${missing.map(skillFile).join(' or ')} — then retry the edit.`,

// Path-scoped skills: every skill an active pack bundles that declares
// `force-load-on-file-edits-paths` under its frontmatter `metadata` (the files a
// file tool may touch only with the skill loaded), and the one question both
// readers ask of them —
// which of those skills does THIS path need that the session has not yet loaded.
// The PreToolUse hook (engine/hooks/pretooluse-command.mjs) asks it before a file
// tool runs, so the skill is loaded before the first edit exists; the
// `skill-loaded-before-editing` work rule asks it of the diff at Stop, which is what
// catches an edit the hook never saw (one made through Bash). One resolver, so the
// two cannot disagree about a pattern.
//
// Pattern grammar is the harness's (memory docs, "path-specific rules"): `**` spans
// directories, `*` and `?` stay inside one segment, `{a,b}` expands, everything
// else is literal, and a pattern is matched against the whole repo-relative path —
// so `wiki/**` is the tree and `**/packs/*/RULES.md` is that file at any depth.
import { join } from 'node:path';
import { skillMetadata } from './skill-frontmatter.mjs';

const RE_SPECIALS = /[.+^${}()|[\]\\]/g;

// `{a,b}` groups multiplied out, innermost first, so the matcher below never sees one.
export function expandBraces(glob) {
  const m = /\{([^{}]*)\}/.exec(glob);
  if (!m) return [glob];
  return m[1].split(',').flatMap((alt) => expandBraces(glob.slice(0, m.index) + alt + glob.slice(m.index + m[0].length)));
}

function oneGlobToSource(glob) {
  let re = '';
  for (let i = 0; i < glob.length; i += 1) {
    const c = glob[i];
    if (c === '*' && glob[i + 1] === '*') {
      // `**/` — zero or more whole segments; a trailing `**` — anything at all.
      if (glob[i + 2] === '/') { re += '(?:.*/)?'; i += 2; } else { re += '.*'; i += 1; }
    } else if (c === '*') re += '[^/]*';
    else if (c === '?') re += '[^/]';
    else re += c.replace(RE_SPECIALS, '\\$&');
  }
  return re;
}

export function globToRegExp(glob) {
  return new RegExp(`^(?:${expandBraces(glob).map(oneGlobToSource).join('|')})$`);
}

// The scoped skills of the given packs, flattened: [{ pack, skill, dir, files, re }], one
// entry per pattern. Callers pass the ACTIVE packs — activation is the registry's
// call, not this module's — so an undeclared pack's skills bind nothing. Read off each
// pack's own `skills` list (the convention fills it from the directory), so a skill the
// manifest withholds is not scoped either.
