// writing-pack-prose skill.
//
// Two-root form: the path pattern keys on the `packs/<pack>/` suffix, so it
// matches the canon home's `packs/` and a member's `.claudinite/local/packs/`
// alike (a member's vendored `.claudinite/shared/` copy is linguist-vendored and
// never in the file set).
//
// RELEVANCE FIRST (engine/checks/README.md): the convention is opt-in per rule,
// so a pack with no markers and no check entries produces nothing.
const PROSE = /(^|\/)packs\/[^/]+\/(?:RULES\.md|skills\/[^/]+\/SKILL\.md)$/;
const PACK_DIR = /(^|.*\/)packs\/[^/]+\//;

// A citation marker: a line ENDING with `(3)` or `(3, 7)` — an inline issue id
// `(#1119)` or a worded parenthetical never matches, and a trailing period puts
// the marker after it by convention. A marker resolves within its own file's
// namespace: `(3)` in RULES.md cites the `RULES-3` entry, in a skill the
// `<skill-name>-3` entry.
const MARKER = /\((\d+(?:\s*,\s*\d+)*)\)\s*$/;
const ENTRY = /^\s*-\s+\*\*\(([A-Za-z][\w-]*-\d+)\)\*\*/;
const CHECK_ENTRY = /^\s*-\s+\*\*\(check:([\w/-]+)\)\*\*/;

// A check id as pack files spell it: declared-checks.json's `"id": "x"` or a
// coded rule module's `id: 'x'` — a pack-prefixed id (`aws-sam/handler-path`)
// carries a slash.
const CHECK_IDS = /\bid['"]?\s*:\s*['"]([\w/-]+)['"]/g;

const rule = {
  id: 'references-integrity',
  severity: 'blocking',
  since: '2026-09-01',
  description: 'Every (n) rationale marker in pack prose resolves to an entry in that pack\'s references.md, and every check: entry there names a check the pack still carries',
  doc: 'packs/claudinite-growth/skills/writing-pack-prose/SKILL.md',
  why: 'the references doc is what a periodic review reaffirms rules and checks against — a dangling marker cites a rationale nobody recorded, and an orphaned check entry lets a review reaffirm a check that no longer exists',

  run(ctx) {
    const out = [];
    const entriesOf = new Map(); // pack dir -> Set of entry numbers, or null when no references.md

    const entries = (packDir) => {
      if (!entriesOf.has(packDir)) {
        const text = ctx.read(`${packDir}references.md`);
        entriesOf.set(packDir, text === null
          ? null
          : new Set(text.split('\n').map((l) => ENTRY.exec(l)?.[1]).filter(Boolean)));
      }
      return entriesOf.get(packDir);
    };

    for (const file of ctx.files) {
      if (!PROSE.test(file)) continue;
      const text = ctx.read(file);
      if (text === null) continue;
      const packDir = PACK_DIR.exec(file)[0];
      // The file's entry namespace: RULES for RULES.md, the skill's own name
      // for a skills/<name>/SKILL.md.
      const stem = file.endsWith('/RULES.md') || file === 'RULES.md'
        ? 'RULES'
        : file.split('/').at(-2);
      for (const line of text.split('\n')) {
        const m = MARKER.exec(line);
        if (!m) continue;
        const known = entries(packDir);
        for (const n of m[1].split(',').map((s) => s.trim())) {
          const key = `${stem}-${n}`;
          if (known === null) {
            out.push(finding(rule, {
              file,
              what: `cites rationale entry (${n}) but the pack has no references.md`,
              fix: `add ${packDir}references.md with a "- **(${key})** <reason>" entry, or drop the marker — the writing-pack-prose skill owns the convention`,
            }));
          } else if (!known.has(key)) {
            out.push(finding(rule, {
              file,
              what: `cites rationale entry (${n}), which ${packDir}references.md does not carry as ${key}`,
              fix: `add the "- **(${key})** <reason>" entry, or drop the marker; entry numbers are stable identifiers, so a removed entry's number is never reused`,
            }));
          }
        }
      }
    }

    // The reverse direction: check entries against the checks the pack carries.
    for (const file of ctx.files) {
      if (!/(^|\/)(?:local_)?packs\/[^/]+\/references\.md$/.test(file)) continue;
      const text = ctx.read(file);
      if (text === null) continue;
      const packDir = PACK_DIR.exec(file)[0];
      const cited = text.split('\n').map((l) => CHECK_ENTRY.exec(l)?.[1]).filter(Boolean);
      if (!cited.length) continue;
      const ids = new Set();
      for (const f of ctx.files) {
        if (!f.startsWith(packDir) || !/\.(mjs|json)$/.test(f)) continue;
        for (const m of (ctx.read(f) ?? '').matchAll(CHECK_IDS)) ids.add(m[1]);
      }
      for (const id of cited) {
        if (ids.has(id)) continue;
        out.push(finding(rule, {
          file,
          what: `carries a rationale entry for check:${id}, which the pack does not carry`,
          fix: 'remove the entry with the check it explained, or point it at the check\'s current id',
        }));
      }
    }
    return out;
  },
};

export default rule;
=====CLAIMED-ONCE=====
import { finding } from '../../../engine/checks/helpers/findings.mjs';
import { parseVersion, formatVersion } from '../../../engine/version.mjs';
import { VERSIONS_FILENAME, rowVersions } from '../workRules/pack-version-bumped.mjs';

// A PACK VERSION IS AN IDENTITY, NOT A COUNTER. `planPackUpdates` re-fetches a
// pack directory only where `installed < canon`, so the number is the fleet's
// whole name for a set of bytes. Two changes landing under one number means the
// members that converged between the two merges hold the first one's tree
// stamped with a number the second one also claims — and no converge will ever
// correct them, because their stamp already reads as current.
//
// That is not a hypothetical, and it is not an authoring mistake `pack-version-bumped`
// could have caught. Two branches cut from the same main both bump to the same
// next version, both record their row, both go green — each answered "did THIS
// change move the version" correctly and yes — and `pack.mjs` then AUTO-MERGES,
// because the two sides wrote identical bytes. Git has nothing to flag. #1482 is
// what it cost: #1466's janitor rule widening reached no member, the fleet swept
// with the old code, and the members' stamps read exactly as they should.
//
// THE ENGINE HAS NO TWIN OF THIS. `engine-release-record` (the claudinite local
// pack) is `pack-version-bumped`'s sibling, but the engine tree vendors WHOLESALE
// on every converge — its version records what landed, it does not gate what
// ships — so two releases sharing a number strand no content and there is nothing
// here to widen onto `engine/RELEASES.md`.
//
// THE DELIVERY half of that is `ci-work-scope.mjs` judging a push onto main
// against what the branch held before it, which re-asks `pack-version-bumped`
// where both branches are visible and so catches the collision as it lands.
// This is the RECORD half, and it is not the same
// question: a collision that landed before that gate existed left no red run
// behind, only two rows, and "what did version N change?" has two answers for
// as long as they both stand.
//
// WORLD SCOPE, because two rows claiming one number is a property of the tree,
// not of any diff — neither branch wrote both. `pack-version-bumped` forces a
// row for every bump, so a collision always leaves one.
const rule = {
  id: 'pack-version-claimed-once',
  severity: 'blocking',
  description: "No two rows of a pack's VERSIONS.md claim the same version",
  doc: 'packs/claudinite-canon-curation/README.md',
  why: 'a member re-fetches a pack only when canon\'s version exceeds its installed one, so two changes sharing a number leave whichever members converged between the two merges holding the first tree stamped with the second\'s number — permanently, with nothing red to say so (#1482)',

  run(ctx) {
    const findings = [];
    const logs = ctx.files.filter((f) => f.startsWith('packs/')
      && f.endsWith(`/${VERSIONS_FILENAME}`) && f.split('/').length === 3);
    for (const file of logs) {
      const seen = new Map();
      for (const { version, line } of rowVersions(ctx.read(file))) {
        const parsed = parseVersion(version);
        if (!parsed) continue;                    // not a version at all — the row shape is another rule's question
        const key = formatVersion(parsed);
        if (!seen.has(key)) { seen.set(key, line); continue; }
        findings.push(finding(rule, {
          file,
          line,
          what: `version ${version} is claimed by two rows (also line ${seen.get(key)}), so two changes shipped under one number`,
          fix: `fold the two rows into one saying what version ${version} carries — the members that took it between the two merges `
            + `hold one of them and will never be sent the other — and bump the pack to a fresh version, with its own row, to `
            + `re-deliver the content that was stranded`,
        }));
      }
    }
    return findings;
  },
};

export default rule;

