{
  "id": "catalog-completeness",
  "severity": "blocking",
  "failureMessage": "a hand-maintained catalog that omits a real pack misroutes readers and hides capability; the check keeps the index honest against the tree",
  "relevantWhen": {
    "trackedFileMatches": "/^engine\\/pack_loader\\/pack-registry\\.mjs$/"
  },
  "requireIndexCoverage": [
    {
      "eachTrackedPathMatching": "/^packs\\/(?<name>[^/]+)\\/pack\\.mjs$/",
      "indexFile": "packs/README.md",
      "coveredByText": "({name}/",
      "whenIndexFileAbsent": "assertNothing",
      "anchorFindingsAt": "indexFile",
      "what": "the pack \"{name}\" exists on disk but is not listed in packs/README.md",
      "fix": "add a \"{name}\" entry to packs/README.md (or delete the pack if it is dead)"
    }
  ]
}

